class SagaOrchestrator:
    def __init__(self, store, bus):
        self.store = store  # durable: saga_id -> {state, step, compensations[]}
        self.bus = bus

    def execute(self, saga_id, steps):
        # steps: [(action, compensation), ...]
        state = self.store.load(saga_id) or {"step": 0, "stack": []}
        for i in range(state["step"], len(steps)):
            action, comp = steps[i]
            # persist BEFORE send: crash here must not lose intent
            self.store.save(saga_id, {"step": i, "stack": state["stack"]})
            # idempotency key = saga_id + step index; handler must dedupe
            ok = self.bus.send(action, idem_key=f"{saga_id}:{i}")
            if not ok:
                self.compensate(saga_id, state["stack"])
                return "ABORTED"
            state["stack"].append(comp)
            state["step"] = i + 1
        self.store.save(saga_id, {"step": len(steps), "stack": state["stack"]})
        return "COMMITTED"

    def compensate(self, saga_id, stack):
        for comp in reversed(stack):
            # compensations must be retryable; never give up silently
            self.bus.send_until_ack(comp, idem_key=f"{saga_id}:c:{comp}")
        self.store.mark_aborted(saga_id)
